mapper.update:
UPDATE sol_preparation SET content_version = content_version + 1,
    version = version + 1, updater = #{update.updater}, update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{update.tenantId} AND id = #{update.preparationId}
  AND preparation_type_code = 'PRE_04_REQUIREMENT_ANALYSIS'
  AND status_code = 'DRAFT' AND draft_marker = 1
  AND version = #{update.expectedVersion} AND content_version = #{update.expectedContentVersion}

UPDATE sol_preparation SET content_version = content_version + 1,
    version = version + 1, updater = #{update.updater}, update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{update.tenantId} AND id = #{update.preparationId}
  AND preparation_type_code = 'PRE_04_REQUIREMENT_ANALYSIS'
  AND status_code = 'DRAFT' AND draft_marker = 1
  AND version = #{update.expectedVersion}

UPDATE sol_preparation SET effective_marker = NULL, version = version + 1,
    updater = #{update.updater}, update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{update.tenantId} AND id = #{update.preparationId}
  AND preparation_type_code = 'PRE_04_REQUIREMENT_ANALYSIS'
  AND status_code = 'COMPLETED' AND effective_marker = 1
  AND version = #{update.expectedVersion}
